extern void EPD_IO_WriteReg(uint8_t Reg);
extern void EPD_IO_WriteData(uint16_t RegValue);

void SUDO_EPD_DrawLandscape(const uint8_t *pdata)
{
    // 1. Апаратне вікно (128x250)
    EPD_IO_WriteReg(0x44); // RAM X (коротка вісь)
    EPD_IO_WriteData(0x00);
    EPD_IO_WriteData(0x0F); // 15 (це 16 байт = 128 пікселів)
    
    EPD_IO_WriteReg(0x45); // RAM Y (довга вісь)
    EPD_IO_WriteData(0x00); EPD_IO_WriteData(0x00);
    EPD_IO_WriteData(249 & 0xFF); EPD_IO_WriteData((249 >> 8) & 0xFF);
    
    // 2. Вказівник запису в (0, 0)
    EPD_IO_WriteReg(0x4E); EPD_IO_WriteData(0x00);
    EPD_IO_WriteReg(0x4F); EPD_IO_WriteData(0x00); EPD_IO_WriteData(0x00);
    
    // 3. Команда запису
    EPD_IO_WriteReg(0x24);
    
    // 4. Попіксельний 1-бітний рендер з поворотом на 90 градусів
    for (uint16_t phys_y = 0; phys_y < 250; phys_y++) 
    {
        // 16 байт на фізичний рядок (128 пікселів)
        for (uint16_t phys_x_byte = 0; phys_x_byte < 16; phys_x_byte++) 
        {
            uint8_t out_byte = 0x00; 
            
            for (uint8_t bit = 0; bit < 8; bit++) 
            {
                uint16_t phys_x = phys_x_byte * 8 + bit;
                
                // Математика повороту (Landscape 248x128 -> Portrait 128x250)
                uint16_t land_x = phys_y;
                int16_t land_y = 127 - phys_x;
                
                uint8_t is_black = 0; // Білий фон за межами картинки
                
                // Якщо ми всередині масиву 248x128
                if (land_x < 248 && land_y >= 0 && land_y < 128) 
                {
                    uint16_t byte_idx = land_y * 31 + (land_x / 8);
                    uint8_t bit_idx = 7 - (land_x % 8);
                    is_black = (pdata[byte_idx] >> bit_idx) & 0x01;
                }
                
                // Для цього екрана зазвичай 1 = Білий, 0 = Чорний.
                // Якщо піксель не чорний, записуємо 1.
                if (!is_black) 
                {
                    out_byte |= (1 << (7 - bit));
                }
            }
            
            EPD_IO_WriteData(out_byte);
        }
    }
}
/* USER CODE END PFP */

